export class TaskStore {
  private tasks: Task[] = [];

  constructor() {}

  create(taskTitle: string, priority?: number, dueDate?: Date): void {
    const task: Task = {
      id: this.tasks.length + 1,
      title: taskTitle,
      priority: priority || 1,
      dueDate: dueDate || null,
      completed: false,
    };
    this.tasks.push(task);
  }

  getAll(): Task[] {
    return this.tasks;
  }

  complete(id: number): void {
    const task = this.tasks.find(t => t.id === id);
    if (task) {
      task.completed = true;
    }
  }
}

export interface Task {
  id: number;
  title: string;
  priority: number;
  dueDate: Date | null;
  completed: boolean;
}

import { TaskStore, Task } from '../core-engine/core-engine.ts';

export function render(container: HTMLElement) {
  container.innerHTML = `
    <div class="app">
      <h1>Task List</h1>
      <div class="row">
        <input id="taskTitle" type="text" placeholder="Enter task title" />
        <button id="addTask" class="btn">Add Task</button>
      </div>
      <div class="row">
        <button id="taskList" class="btn">Task List</button>
        <button id="completeTask" class="btn">Complete Task</button>
        <button id="deleteTask" class="btn">Delete Task</button>
        <button id="editTask" class="btn">Edit Task</button>
      </div>
    </div>
  `;

  const taskTitleInput = document.getElementById('taskTitle') as HTMLInputElement;
  const addTaskBtn = document.getElementById('addTask') as HTMLButtonElement;
  const taskListBtn = document.getElementById('taskList') as HTMLButtonElement;
  const completeTaskBtn = document.getElementById('completeTask') as HTMLButtonElement;
  const deleteTaskBtn = document.getElementById('deleteTask') as HTMLButtonElement;
  const editTaskBtn = document.getElementById('editTask') as HTMLButtonElement;

  const taskStore = new TaskStore();

  addTaskBtn.addEventListener('click', () => {
    const title = taskTitleInput.value.trim();
    if (title) {
      taskStore.create(title);
      taskTitleInput.value = '';
      render(container);
    }
  });

  taskListBtn.addEventListener('click', () => {
    const tasks = taskStore.getAll();
    const taskList = document.createElement('div');
    taskList.className = 'grid';
    tasks.forEach(task => {
      const card = document.createElement('div');
      card.className = 'card';
      card.innerHTML = `
        <h3>${task.title}</h3>
        <p>Priority: ${task.priority}</p>
        <p>Due Date: ${task.dueDate ? task.dueDate.toISOString() : 'N/A'}</p>
        <p>Completed: ${task.completed ? '✓' : '✗'}</p>
      `;
      taskList.appendChild(card);
    });
    container.appendChild(taskList);
  });

  completeTaskBtn.addEventListener('click', () => {
    const taskId = parseInt(prompt('Enter task ID to complete:'));
    if (taskId) {
      taskStore.complete(taskId);
      render(container);
    }
  });

  deleteTaskBtn.addEventListener('click', () => {
    const taskId = parseInt(prompt('Enter task ID to delete:'));
    if (taskId) {
      taskStore.delete(taskId);
      render(container);
    }
  });

  editTaskBtn.addEventListener('click', () => {
    const taskId = parseInt(prompt('Enter task ID to edit:'));
    if (taskId) {
      const newTitle = prompt('Enter new task title:');
      if (newTitle) {
        taskStore.edit(taskId, newTitle);
        render(container);
      }
    }
  });
}

import { TaskStore, Task } from '../core-engine/core-engine.ts';

export async function handleTodoInput(input: string) {
  try {
    const parsedInput = parseTodoInput(input);
    await processTask(parsedInput);
  } catch (error) {
    console.error('Error processing todo input:', error);
    return null;
  }
}

function parseTodoInput(input: string): Partial<Task> {
  const parts = input.split(',');
  const [title, priority, dueDate] = parts.map((part) => part.trim());
  if (priority && !Number.isInteger(parseInt(priority))) {
    throw new Error('Invalid or out-of-range priority');
  }
  if (!dueDate || isNaN(Date.parse(dueDate.toString()))) {
    throw new Error('Invalid date format or NaN due date');
  }
  return { title, priority: parseInt(priority), dueDate: new Date(dueDate) };
}

async function processTask(task: Partial<Task>): Promise<void> {
  const taskStore = new TaskStore();
  await taskStore.create(task.title, task.priority, task.dueDate);
}

export class TaskStore {
  private tasks: Record<string, Task> = {};

  public async create(title: string, priority: number, dueDate: Date): Promise<void> {
    const existingTask = this.getTask(title);
    if (existingTask) {
      throw new Error('Task with the same title already exists');
    }

    const task = { title, priority, dueDate };
    this.tasks[title] = task;

    // Write to persistence (local storage for simplicity)
    localStorage.setItem(`Task_${title}`, JSON.stringify(task));
  }

  public async getAllTasks(): Promise<Task[]> {
    const taskList: Task[] = [];
    for (const key in this.tasks) {
      if (this.tasks.hasOwnProperty(key)) {
        taskList.push(this.tasks[key]);
      }
    }
    return taskList;
  }

  public async completeTask(title: string): Promise<void> {
    const existingTask = this.getTask(title);
    if (!existingTask) {
      throw new Error('No task with the title found');
    }

    delete this.tasks[title];

    // Write to persistence (local storage for simplicity)
    localStorage.removeItem(`Task_${title}`);
  }

  private getTask(title: string): Task | undefined {
    return this.tasks[title];
  }
}

